python3 -c "
import json
with open('/app/resources/treasury_bulletin_2010_06.json', 'r') as f:
    data = json.load(f)

# Search for keys containing 'Liabilities' and 'Derivatives'
def find_keys(d, prefix=''):
    result = []
    if isinstance(d, dict):
        for k, v in d.items():
            result.extend(find_keys(v, prefix + k + '.'))
    elif isinstance(d, list) and len(d) > 0:
        if isinstance(d[0], dict):
            for item in d[:3]:
                result.extend(find_keys(item, prefix))
    return result

# Print structure
print(type(data))
if isinstance(data, dict):
    print(list(data.keys())[:20])
elif isinstance(data, list):
    print('List length:', len(data))
    if len(data) > 0:
        print('First item type:', type(data[0]))
"
